<dialog id="job-wizard" aria-labelledby="job-wizard-title">
<form id="job-wizard-form" class="stack">
<header class="job-wizard-header"><div><h2 id="job-wizard-title">New job</h2><p id="job-step-label" class="caption"></p></div><button class="button" id="job-wizard-close" type="button">Close</button></header>
<p id="job-wizard-status" role="status" aria-live="polite"></p>
<section data-job-step="0" class="stack"><section id="job-ticket-summary" hidden aria-label="Ticket to move"><h3>Ticket to move</h3><p id="job-ticket-title"></p><p id="job-ticket-description" class="work-detail"></p><p class="caption">Review the existing ticket, then choose its department, project, person and building. This step changes no ticket details.</p></section><label id="job-title-field">Work name<input id="job-title" maxlength="100"></label><label id="job-description-field">Job details<textarea id="job-description" maxlength="5000" rows="4"></textarea></label><div class="field-pair" id="job-classification"><label>Job type<span class="request-select"><select id="job-type"><option value="general">General request</option><option value="it_support">IT support</option><option value="event_setup">Event setup</option><option value="plumbing">Plumbing</option><option value="lighting">Lighting</option><option value="maintenance">Maintenance</option></select></span></label><label>Work priority<span class="request-select"><select id="job-priority"><option value="low">Low</option><option value="normal" selected>Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></span></label></div><label id="job-due-field">Job / task due date<input id="job-due" type="date"></label><p id="job-operation-warning" class="caption"></p></section>
<section data-job-step="1" class="stack" hidden><label>Work department<span class="request-select"><select id="job-department"></select></span></label><label id="job-project-field">Project<span class="request-select"><select id="job-project"></select></span></label><label id="job-person-field">Person assigned<span class="request-select"><select id="job-person"></select></span></label><label id="job-building-field">Saved building<span class="request-select"><select id="job-building"></select></span></label><label id="job-location-field">Work location label<input id="job-location" maxlength="200"></label><p id="job-target-coverage" class="caption"></p></section>
<section data-job-step="2" class="stack" hidden><h3>Review before saving</h3><dl id="job-review"></dl><label id="job-confirm-field" hidden><input id="job-confirm" type="checkbox"> <span id="job-confirm-copy"></span></label><p class="caption">Changes use the current department, record versions and existing member access. No account or access grant is created.</p></section>
<div class="actions"><button class="button" type="button" id="job-back">Back</button><button class="button primary" type="button" id="job-next">Next</button><button class="button primary" type="submit" id="job-save" hidden>Save</button><button class="button" type="button" id="job-retry" hidden>Retry the same action</button></div>
</form></dialog>
